const fs = require('fs');

const lines = fs.readFileSync(0, 'utf8').trim().split('\n');
const [L, C] = lines[0].trim().split(' ').map(Number);
const grid = lines.slice(1, 1 + L).map(line => line.trim());

let sr = -1, sc = -1;
for (let i = 0; i < L; i++) {
  for (let j = 0; j < C; j++) {
    if (grid[i][j] === 'o') {
      sr = i;
      sc = j;
      break;
    }
  }
  if (sr !== -1) break;
}

const dirs = [
  [-1, 0],
  [1, 0],
  [0, -1],
  [0, 1]
];

let prevR = -1, prevC = -1;
let curR = sr, curC = sc;

while (true) {
  let nextR = -1, nextC = -1;

  for (const [dr, dc] of dirs) {
    const nr = curR + dr;
    const nc = curC + dc;

    if (nr < 0 || nr >= L || nc < 0 || nc >= C) continue;
    if (grid[nr][nc] === '.') continue;
    if (nr === prevR && nc === prevC) continue;

    nextR = nr;
    nextC = nc;
    break;
  }

  if (nextR === -1) break;

  prevR = curR;
  prevC = curC;
  curR = nextR;
  curC = nextC;
}

console.log(`${curR + 1} ${curC + 1}`);
